  "settings.aiPrivacy.meaningContentContext": "페이지와 영상 제목, YouTube 채널명과 영상 카테고리, 정규화한 Reddit 커뮤니티명을 각각 정해진 길이로 잘라 보냅니다. 페이지 원문, 문서·메모·메시지 본문은 포함되지 않습니다. Reddit 커뮤니티는 주소뿐 아니라 페이지·창 제목에서도 읽히기 때문에, 이 항목과 페이지 주소 중 하나만 켜져 있어도 전송될 수 있습니다. 고급 맥락은 아래의 별도 제품 항목에서 안내합니다.",
