  "settings.aiPrivacy.rowMemory": "최근 활동 맥락",
  "settings.aiPrivacy.rowEnhancedContext": "고급 맥락",
  "settings.aiPrivacy.valueEnhancedContext": "워크스페이스·프로젝트·폴더·저장소·대화·문서 이름과 유형, 제목 구조, 태그·라벨, 제한된 짧은 힌트",
  "settings.aiPrivacy.valueEnhancedContextOff": "사용 불가 — 이 재시도에 보낼 수 있는 안전한 고급 맥락이 없습니다",
  "settings.aiPrivacy.noteEnhancedContext": "재시도 1회당 항목 최대 5개, 항목마다 값 최대 5개, 짧은 힌트는 240자로 잘라서 전송. 각 항목에는 출처 종류·깊이·유형·전송 판정이 함께 붙습니다.",
  "settings.aiPrivacy.noteEnhancedContextOff": "현재 분류 환경에는 재시도에 사용할 수 있는 안전한 고급 맥락이 없습니다.",
  "settings.aiPrivacy.stateEnhancedContextOff": "꺼짐",
  "settings.aiPrivacy.stateEnhancedContextOn": "로컬·BYOK 재시도에만",
  "settings.aiPrivacy.meaningEnhancedContext": "고급 맥락은 기본으로 켜져 있으며, 첫 분류가 확신을 얻지 못해 다시 시도할 때만 로컬 AI·셀프 호스팅·내 API 키 제공업체 경로로 전송됩니다. Drifty 클라우드 경로는 이 항목을 받지 않습니다.",
  "settings.aiPrivacy.meaningEnhancedContextDetail": "무엇을 하고 있었는지에 대한 로컬 파생 맥락으로 워크스페이스·프로젝트·폴더·저장소, 제목 구조, 태그, 라벨, 제한된 짧은 힌트, 정규화한 AI 대화 제목·유형, 개발 워크스페이스, 문서 제목·유형이 들어가며, 항목마다 출처 종류·깊이·유형·전송 판정이 함께 붙습니다. 이 값은 Drifty가 이미 수집하던 앱·창·사이트 제목·URL 메타데이터에서 파생하며 먼저 로컬에서 걸러지고 가려집니다. 프롬프트·응답·터미널 명령·문서 본문·메시지 본문·수집기 원본 출력은 아예 차단되고, 비밀키·토큰·카드번호 같은 식별자는 제거됩니다. 검증된 메신저 화면에서는 워크스페이스·채널·폴더·채널 유형만 보낼 수 있으며, DM 상대 이름·메일 제목·계정 주소·메시지 본문은 계속 제외됩니다.",
  "settings.aiPrivacy.valueMemory": "직전 구간들을 압축한 요약과 저장된 업무 맥락",
  "settings.aiPrivacy.noteMemory": "요청 안의 구간마다 요약이 하나씩 붙고, 각 요약은 최대 8개 전환(앱·도메인·제목)을 담습니다. 저장된 업무 맥락은 요청당 하나입니다.",
  "settings.aiPrivacy.valueMemoryNoProfile": "직전 구간들을 압축한 요약",
  "settings.aiPrivacy.noteMemoryNoProfile": "요청 안의 구간마다 요약이 하나씩 붙고, 각 요약은 최대 8개 전환(앱·도메인·제목)을 담습니다. 업무 프로필이 꺼져 있어 저장된 업무 맥락은 빠집니다.",
  "settings.aiPrivacy.meaningMemory": "모델이 구간을 따로 떨어진 점으로 보지 않도록, 요청에 들어간 구간마다 압축 요약을 하나씩 붙입니다. 각 요약은 앱 이름·도메인·제목이 들어있는 최근 전환을 최대 8개까지 담고, 전체 크기도 제한됩니다. 따라서 20개 구간을 보내면 요약도 최대 20개가 함께 갑니다. 타임라인 사본은 아닙니다.",
  "settings.aiPrivacy.footnote": "모든 요청에는 구간의 로컬 ID와 위 항목들의 지문값도 들어갑니다. 이전 분류 결과를 재사용하기 위한 값입니다.",
  "settings.aiPrivacy.footnoteCloud": "Drifty 버전과 설치별 기기 ID는 Drifty 클라우드로 보낼 때만 붙고, 내 API 키로 직접 호출할 때는 포함되지 않습니다.",
  "settings.aiPrivacy.footnoteSamples": "클라우드로 보낼 때는 분류 품질 개선을 위해 위와 같은 최소화된 항목이 샘플로 보관될 수 있습니다. 계정에서 개별 샘플을 열람할 수는 없지만, 계정을 삭제하면 현재 및 이전 솔트 계정 해시에 연결된 샘플이 삭제됩니다. 비가역 솔트 해시 표식은 삭제된 샘플이 다시 생성되지 않도록 24시간 차단하며, 만료된 표식은 이후 샘플 정리 과정에서 제거됩니다. 샘플 저장소에는 Drifty 서비스 내부에서만 접근할 수 있습니다.",
  "settings.aiPrivacy.glossaryHeading": "각 항목의 의미",
