  "settings.aiPrivacy.providerKeysReceipt": "키는 운영체제의 자격 증명 저장소에 보관되며 분류 데이터에는 절대 포함되지 않습니다. 다만 Drifty가 제공업체 API를 호출할 때 인증 수단으로는 전송됩니다. 원래 그런 용도입니다.",
