  "settings.account.deleteErrorBillingStopped": "결제 고객 정리는 완료됐습니다. 활성 Pro 구독이 있었다면 종료됐지만 계정 삭제는 끝나지 않았습니다. 다시 시도해 남은 정리를 완료해 주세요.",
