  "settings.account.deleteErrorLocalSync": "이 Mac의 동기화 식별자를 안전하게 초기화하지 못해 클라우드 삭제를 시작하지 않았습니다. Drifty를 재시작한 뒤 다시 시도해 주세요.",
  "settings.account.deleteErrorLocalCalendar": "이 Mac의 Google Calendar 자격 증명을 제거하지 못해 클라우드 삭제를 시작하지 않았습니다. 계정 설정에서 Calendar 연결을 해제한 뒤 다시 시도해 주세요.",
  "settings.account.deleteErrorSharedTeam": "다른 멤버의 데이터를 보호하기 위해 계정 삭제를 차단했습니다. 조직 좌석으로 앱을 쓰고 있다면 계정 설정에서 먼저 조직을 나가 주세요. Teams 베타는 아직 공유 공간의 소유권 이전이나 직접 정리를 지원하지 않습니다.",
  "settings.account.deleteErrorSharedTeamAfterBilling": "결제 고객 정리는 완료됐습니다. 최종 삭제 직전에 다른 멤버나 공유 프로젝트 데이터가 확인되어 계정 삭제는 차단된 상태입니다. Teams 베타는 아직 이 경우의 직접 정리를 지원하지 않습니다.",
